import{_ as t,o,c as r,l as n,t as a,N as s}from"./chunks/framework.Gjrf2Eoj.js";const w=JSON.parse('{"title":"chown | x-cmd man (man1) | change file owner and group","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | chown - change file owner and group","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"chown | x-cmd man (man1) | change file owner and group"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | chown - change file owner and group"}]]},"headers":[],"params":{"isMan":true,"man":"chown","category":"man1","desc":"change file owner and group"},"relativePath":"man1/chown.md","filePath":"man1/chown.md"}'),i={name:"man1/chown.md"},d={class:"visually-hidden"},h=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>chown - change file owner and group</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>chown</strong> [<em>OPTION</em>]... [<em>OWNER</em>][<em>:</em>[<em>GROUP</em>]] <em>FILE</em>... <br> <strong>chown</strong> [<em>OPTION</em>]... <em>--reference=RFILE FILE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This manual page documents the GNU version of <strong>chown</strong>. <strong>chown</strong> changes the user and/or group ownership of each given file. If only an owner (a user name or numeric user ID) is given, that user is made the owner of each given file, and the files&#39; group is not changed. If the owner is followed by a colon and a group name (or numeric group ID), with no spaces between them, the group ownership of the files is changed as well. If a colon but no group name follows the user name, that user is made the owner of the files and the group of the files is changed to that user&#39;s login group. If the colon and group are given, but the owner is omitted, only the group of the files is changed; in this case, <strong>chown</strong> performs the same function as <strong>chgrp</strong>. If only a colon is given, or if the entire operand is empty, neither the owner nor the group is changed.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>Change the owner and/or group of each FILE to OWNER and/or GROUP. With <strong>--reference</strong>, change the owner and group of each FILE to those of RFILE.</p><dl><dt><strong>-c</strong>, <strong>--changes</strong></dt><dd>like verbose but report only when a change is made</dd><dt><strong>-f</strong>, <strong>--silent</strong>, <strong>--quiet</strong></dt><dd>suppress most error messages</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>output a diagnostic for every file processed</dd><dt><strong>--dereference</strong></dt><dd>affect the referent of each symbolic link (this is the default), rather than the symbolic link itself</dd><dt><strong>-h</strong>, <strong>--no-dereference</strong></dt><dd>affect symbolic links instead of any referenced file (useful only on systems that can change the ownership of a symlink)</dd><dt><strong>--from</strong>=<em>CURRENT_OWNER</em>:CURRENT_GROUP</dt><dd>change the owner and/or group of each file only if its current owner and/or group match those specified here. Either may be omitted, in which case a match is not required for the omitted attribute</dd><dt><strong>--no-preserve-root</strong></dt><dd>do not treat &#39;/&#39; specially (the default)</dd><dt><strong>--preserve-root</strong></dt><dd>fail to operate recursively on &#39;/&#39;</dd><dt><strong>--reference</strong>=<em>RFILE</em></dt><dd>use RFILE&#39;s owner and group rather than specifying OWNER:GROUP values. RFILE is always dereferenced.</dd><dt><strong>-R</strong>, <strong>--recursive</strong></dt><dd>operate on files and directories recursively</dd></dl><p>The following options modify how a hierarchy is traversed when the <strong>-R</strong> option is also specified. If more than one is specified, only the final one takes effect.</p><dl><dt><strong>-H</strong></dt><dd>if a command line argument is a symbolic link to a directory, traverse it</dd><dt><strong>-L</strong></dt><dd>traverse every symbolic link to a directory encountered</dd><dt><strong>-P</strong></dt><dd>do not traverse any symbolic links (default)</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Owner is unchanged if missing. Group is unchanged if missing, but changed to login group if implied by a &#39;:&#39; following a symbolic OWNER. OWNER and GROUP may be numeric as well as symbolic.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><dl><dt>chown root /u</dt><dd>Change the owner of /u to &quot;root&quot;.</dd><dt>chown root:staff /u</dt><dd>Likewise, but also change its group to &quot;staff&quot;.</dd><dt>chown -hR root /u</dt><dd>Change the owner of /u and subfiles to &quot;root&quot;.</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by David MacKenzie and Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>chown</strong>(2)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/chown%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/chown\\</a>&gt; <br> or available locally via: info &#39;(coreutils) chown invocation&#39;</p>',23);function l(e,c,g,u,f,p){return o(),r("div",null,[n("h1",d,a(e.$params.man),1),h])}const b=t(i,[["render",l]]);export{w as __pageData,b as default};
